def feature(s):
    s = s or {}
    v = s.get('volume_per_atom_A3')
    if v is not None and v > 0:
        return float(v)
    sites = s.get('sites') or []
    n = sum((a.get('occupancy', 1.0) or 0.0) for a in sites)
    lattice = s.get('lattice') or {}
    v = lattice.get('volume_A3')
    if v is None or n <= 0:
        return 0.0
    return float(v / n)

