def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    properties = s.get('element_properties') or {}
    total = 0.0
    atoms = 0.0
    for site in sites:
        p = properties.get(site.get('element')) or {}
        r = p.get('covalent_radius_A') or 1.3
        w = site.get('occupancy', 1.0) or 0.0
        total = total + w * r * r * r
        atoms = atoms + w
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or volume <= 0:
        v = s.get('volume_per_atom_A3')
        if v is None or v <= 0:
            return 0.0
        volume = v * atoms
    if volume <= 0:
        return 0.0
    return float(4.0 * pi * total / (3.0 * volume))

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    properties = s.get('element_properties') or {}
    radii = [((properties.get(a.get('element')) or {}).get('covalent_radius_A') or 1.3) for a in sites]
    best = None
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if d is None or d <= 0 or i < 0 or j < 0 or i >= len(sites) or j >= len(sites):
            continue
        value = d / (radii[i] + radii[j])
        if best is None or value < best:
            best = value
    if best is None:
        return 0.0
    return float(best)

