    weights = [(a.get('occupancy', 1.0) or 0.0) for a in sites]
    atoms = sum(weights)
    if atoms <= 0:
        return 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if d is None or d <= 0 or i < 0 or j < 0 or i >= len(sites) or j >= len(sites):
