def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    weights = [(a.get('occupancy', 1.0) or 0.0) for a in sites]
    atoms = sum(weights)
    if atoms <= 0:
        return 0.0
    nearest = [7.0 for a in sites]
    edges = s.get('neighbors') or []
    for edge in edges:
        i = edge.get('i', -1)
        d = edge.get('distance_A')
        if i >= 0 and i < n and d is not None and d > 0:
            nearest[i] = min(nearest[i], d)
    counts = [0.0 for a in sites]
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if i >= 0 and i < n and j >= 0 and j < n and d is not None and d > 0:
            if d <= 1.25 * nearest[i]:
                counts[i] = counts[i] + weights[j]
    return float(sum(weights[i] * counts[i] for i in range(n)) / atoms)

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    weights = [(a.get('occupancy', 1.0) or 0.0) for a in sites]
    atoms = sum(weights)
    if atoms <= 0:
        return 0.0
    nearest = [7.0 for a in sites]
    edges = s.get('neighbors') or []
    for edge in edges:
        i = edge.get('i', -1)
        d = edge.get('distance_A')
        if i >= 0 and i < n and d is not None and d > 0:
            nearest[i] = min(nearest[i], d)
    counts = [0.0 for a in sites]
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if i >= 0 and i < n and j >= 0 and j < n and d is not None and d > 0:
            if d <= 1.25 * nearest[i]:
                counts[i] = counts[i] + weights[j]
    mean = sum(weights[i] * counts[i] for i in range(n)) / atoms
    if mean <= 0:
        return 0.0
    variance = sum(weights[i] * (counts[i] - mean) ** 2 for i in range(n)) / atoms
    return float(sqrt(max(0.0, variance)) / mean)

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    nearest = [7.0 for a in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        d = edge.get('distance_A')
        if i >= 0 and i < n and d is not None and d > 0:
            nearest[i] = min(nearest[i], d)
    total = 0.0
    first = 0.0
    second = 0.0
    for i in range(n):
        if nearest[i] < 7.0:
            w = sites[i].get('occupancy', 1.0) or 0.0
            total = total + w
            first = first + w * nearest[i]
            second = second + w * nearest[i] * nearest[i]
    if total <= 0 or first <= 0:
        return 0.0
    mean = first / total
    return float(sqrt(max(0.0, second / total - mean * mean)) / mean)

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    properties = s.get('element_properties') or {}
    en = [(properties.get(a.get('element')) or {}).get('eneg') for a in sites]
    weights = [(a.get('occupancy', 1.0) or 0.0) for a in sites]
    nearest = [7.0 for a in sites]
    edges = s.get('neighbors') or []
    for edge in edges:
        i = edge.get('i', -1)
        d = edge.get('distance_A')
        if i >= 0 and i < n and d is not None and d > 0:
            nearest[i] = min(nearest[i], d)
    total = 0.0
    norm = 0.0
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if i < 0 or j < 0 or i >= n or j >= n or d is None or d <= 0:
            continue
        if d <= 1.25 * nearest[i] and en[i] is not None and en[j] is not None:
            w = weights[i] * weights[j]
            total = total + w * abs(en[i] - en[j])
            norm = norm + w
    if norm <= 0:
        return 0.0
    return float(total / norm)

