def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    properties = s.get('element_properties') or {}
    radii = [((properties.get(a.get('element')) or {}).get('covalent_radius_A') or 1.3) for a in sites]
    weights = [(a.get('occupancy', 1.0) or 0.0) for a in sites]
    eligible = [False for a in sites]
    for i in range(n):
        p = properties.get(sites[i].get('element')) or {}
        en = p.get('eneg')
        group = p.get('group')
        if en is not None and group is not None:
            eligible[i] = en >= 2.5 and group >= 14 and group <= 17
    atoms = sum(weights)
    if atoms <= 0:
        return 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if i < 0 or j < 0 or i >= n or j >= n or d is None or d <= 0:
            continue
        if eligible[i] and eligible[j] and d <= 1.2 * (radii[i] + radii[j]):
            total = total + weights[i] * weights[j]
    return float(total / (2.0 * atoms))

