    s = s or {}
    properties = s.get('element_properties') or {}
    total = 0.0
    norm = 0.0
    for site in s.get('sites') or []:
        p = properties.get(site.get('element')) or {}
        ionization = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if ionization is not None and affinity is not None:
            w = site.get('occupancy', 1.0) or 0.0
            total = total + w * (ionization - affinity) / 2.0
            norm = norm + w
    if norm <= 0:
        return 0.0
    return float(total / norm)

def feature(s):
    s = s or {}
    properties = s.get('element_properties') or {}
    total = 0.0
    second = 0.0
    norm = 0.0
    for site in s.get('sites') or []:
        p = properties.get(site.get('element')) or {}
        ionization = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if ionization is not None and affinity is not None:
            value = (ionization + affinity) / 2.0
            w = site.get('occupancy', 1.0) or 0.0
            total = total + w * value
            second = second + w * value * value
            norm = norm + w
    if norm <= 0:
        return 0.0
    mean = total / norm
    return float(sqrt(max(0.0, second / norm - mean * mean)))

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    properties = s.get('element_properties') or {}
    en = [(properties.get(a.get('element')) or {}).get('eneg') for a in sites]
    radii = [((properties.get(a.get('element')) or {}).get('covalent_radius_A') or 1.3) for a in sites]
    weights = [(a.get('occupancy', 1.0) or 0.0) for a in sites]
    atoms = sum(weights)
    if atoms <= 0:
        return 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if i < 0 or j < 0 or i >= n or j >= n or d is None or d <= 0:
            continue
        if en[i] is None or en[j] is None:
            continue
        contrast = en[i] - en[j]
        scale = radii[i] + radii[j]
        total = total + weights[i] * weights[j] * contrast * contrast * exp(-d / scale) / d
    return float(total / (2.0 * atoms))

def feature(s):
    s = s or {}
    lattice = s.get('lattice') or {}
    lengths = lattice.get('lengths_A')
    if lengths is None:
        matrix = lattice.get('matrix')
        if matrix is None:
            return 0.0
        lengths = [sqrt(sum(x * x for x in row)) for row in matrix]
    positive = [x for x in lengths if x is not None and x > 0]
    if not positive:
        return 0.0
    return float(max(positive) / min(positive))
